{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:#0b1220;--accent:#9bd3c7;--muted:#9aa4ad;--glass:rgba(255,255,255,0.03);--glass-2:rgba(255,255,255,0.02)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#e6eef0;background:linear-gradient(180deg,#081016 0%, #0f1720 100%);}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;border-bottom:1px solid rgba(255,255,255,0.03);backdrop-filter:blur(6px)}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:52px;height:52px;background:linear-gradient(135deg,var(--accent),#6fa1ff);border-radius:10px;display:grid;place-items:center;color:#042; font-weight:700}
    nav a{color:#cfe9e1;text-decoration:none;margin:0 10px;font-size:15px}
    .primary-cta{background:var(--accent);color:#042;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:600}
    main{max-width:1100px;margin:36px auto;padding:0 18px}
    .hero{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:start}
    .hero-card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:28px;border-radius:14px;box-shadow:0 6px 20px rgba(2,6,23,0.6);}
    h1{margin:0 0 8px 0;font-size:28px}
    p.lead{color:var(--muted);margin:0 0 18px}
    .facts{display:flex;gap:12px;margin-top:10px}
    .fact{background:var(--glass);padding:10px 12px;border-radius:10px;font-size:13px}
    .panel{background:var(--card);border-radius:12px;padding:18px;margin-top:18px}

    /* session planner */
    .planner h3{margin:0 0 8px;font-size:18px}
    label{display:block;font-size:13px;margin:10px 0 6px;color:var(--muted)}
    input[type=text],select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:#e6eef0}
    .planner-actions{display:flex;gap:10px;align-items:center;margin-top:12px}
    button{background:#1f2b34;color:#e6eef0;border:0;padding:10px 12px;border-radius:8px;cursor:pointer}
    .btn-ghost{background:transparent;border:1px solid rgba(255,255,255,0.04)}
    .result{white-space:pre-wrap;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:12px;border-radius:8px;margin-top:12px;color:#d7f0ea}
    footer{margin:40px 0;color:var(--muted);font-size:13px;text-align:center}

    /* decorative diagonal split */
    .diagonal{position:absolute;left:0;right:0;height:280px;top:76px;pointer-events:none;mask-image:linear-gradient(180deg,black 60%, transparent 100%)}
    .pattern{position:absolute;inset:0;background-image:url('assets/img/pattern.svg');opacity:0.08;background-repeat:repeat}

    @media(max-width:920px){.hero{grid-template-columns:1fr;padding:0}.hero-card{order:2}.diagonal{display:none}}
  </style>
</head>
<body>
  <div class="diagonal"><div class="pattern"></div></div>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Offerings</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">About</a>
      <a href="faq.html">Help</a>
      <a class="primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <a href="contact.html" style="margin-left:12px;color:var(--muted)">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="hero-card">
        <h1>How we shape the room</h1>
        <p class="lead">We design focused sound environments that guide attention without distraction — a practical container for rest, clarity, and an anchoring pause in your day.</p>
        <div class="facts">
          <div class="fact">Small groups • 12 max</div>
          <div class="fact">Sessions 30–90 minutes</div>
          <div class="fact">City: {{CITY}}, {{STATE}}</div>
        </div>

        <div class="panel" style="margin-top:16px">
          <h3>About our approach</h3>
          <p style="color:var(--muted);margin:8px 0 0">We prioritize practical structure: clear opening, steady sound field, guided closure. Your experience is guided by intentional pacing and simple practices you can take home.</p>
        </div>

        <div class="panel" style="display:flex;gap:12px;flex-wrap:wrap;margin-top:14px">
          <div style="flex:1;min-width:200px">
            <strong>Gatherings</strong>
            <div style="color:var(--muted);font-size:13px">Group sessions for weekly pause</div>
          </div>
          <div style="flex:1;min-width:200px">
            <strong>Private Immersions</strong>
            <div style="color:var(--muted);font-size:13px">Custom sound work for teams or individuals</div>
          </div>
          <div style="flex:1;min-width:200px">
            <strong>VIP Day</strong>
            <div style="color:var(--muted);font-size:13px">A deep, scheduled reset — see pricing</div>
          </div>
        </div>
      </div>

      <aside class="hero-card panel planner">
        <h3>Session Planner</h3>
        <div style="font-size:13px;color:var(--muted);margin-bottom:8px">Design a concise, personalized session you can use at home or bring to a group.</div>
        <label for="goal">Primary focus</label>
        <input id="goal" type="text" placeholder="e.g., wind down after work, creative clarity">

        <label for="length">Length</label>
        <select id="length">
          <option>20 minutes</option>
          <option>30 minutes</option>
          <option>45 minutes</option>
          <option>60 minutes</option>
        </select>

        <label for="instruments">Preferred textures</label>
        <select id="instruments" multiple size="3">
          <option>Gongs</option>
          <option>Tibetan bowls</option>
          <option>Chimes</option>
          <option>Voice / toning</option>
        </select>

        <label for="intensity">Intensity</label>
        <select id="intensity">
          <option>Gentle (soothing)</option>
          <option>Balanced (steady)</option>
          <option>Deep (immersive)</option>
        </select>

        <div class="planner-actions">
          <button id="build">Build plan</button>
          <button id="clear" class="btn-ghost">Reset</button>
        </div>

        <div id="planResult" class="result" aria-live="polite">Use the controls above and click "Build plan" to create your session summary.</div>
        <div style="display:flex;gap:8px;margin-top:8px">
          <button id="copyPlan">Copy summary</button>
          <a href="{{PRIMARY_CTA_URL}}" class="btn-ghost" style="text-decoration:none;display:inline-flex;align-items:center;padding:10px;border-radius:8px">Book a guided session</a>
        </div>
      </aside>
    </section>

    <section style="margin-top:20px;display:grid;grid-template-columns:1fr 320px;gap:18px">
      <div class="panel">
        <h3>Why this works</h3>
        <p style="color:var(--muted)">Our practice uses predictable structure to lower cognitive load: clear openings, tonal scaffolding during the session, and a brief closing ritual. The result is a short, reliable container for changing how your nervous system settles.</p>
        <h4 style="margin-top:12px">Contraindications</h4>
        <p style="color:var(--muted);font-size:13px">If you have active ear infections, recent cranial injury, severe uncontrolled epilepsy, or are pregnant and have been advised to avoid sound therapy, please consult a clinician before attending. If you are on medication that alters consciousness, check with your provider. If in doubt, contact us at {{EMAIL}} or {{PHONE}} before booking.</p>
      </div>

      <div class="panel">
        <h4>Quick links</h4>
        <div style="display:flex;flex-direction:column;gap:8px;margin-top:8px">
          <a href="events.html">See upcoming gatherings</a>
          <a href="private-sessions.html">Private offerings</a>
          <a href="pricing.html">Pricing & packages</a>
        </div>
      </div>
    </section>

    <footer>
      <div style="margin-bottom:8px">Ready to schedule? <a href="{{PRIMARY_CTA_URL}}" style="color:var(--accent);text-decoration:none">Reserve your mat</a></div>
      <div>Questions: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
      <div style="margin-top:10px;color:var(--muted)">© <span id="year"></span> {{BUSINESS_NAME}}</div>
    </footer>
  </main>

  <script>
    document.getElementById('year').textContent = new Date().getFullYear();

    function gatherMulti(select){
      const opts = Array.from(select.options).filter(o=>o.selected).map(o=>o.value);
      return opts.length?opts.join(', '):'No preference';
    }

    const buildBtn = document.getElementById('build');
    const clearBtn = document.getElementById('clear');
    const copyBtn = document.getElementById('copyPlan');
    const result = document.getElementById('planResult');

    buildBtn.addEventListener('click', ()=>{
      const goal = document.getElementById('goal').value.trim() || 'General settling';
      const length = document.getElementById('length').value;
      const instruments = gatherMulti(document.getElementById('instruments'));
      const intensity = document.getElementById('intensity').value;

      const plan = [];
      plan.push('Session Plan — '+goal);
      plan.push('Length: '+length);
      plan.push('Textures: '+instruments);
      plan.push('Intensity: '+intensity);
      plan.push('Structure:');
      plan.push('- Opening (2–5 min): arrive, breath awareness, posture');
      if(intensity.includes('Gentle')) plan.push('- Main ('+length+'): soft tonal layers, long resonance, room for rest');
      else if(intensity.includes('Deep')) plan.push('- Main ('+length+'): sustained harmonic immersion, moderated crescendos, breathable silence');
      else plan.push('- Main ('+length+'): balanced layers, alternating bowls and chime touchpoints');
      plan.push('- Closing (3–6 min): gradual de-escalation, simple grounding prompt');
      plan.push('Notes: Adapt dynamics to participant comfort; offer ear protection if needed.');

      result.textContent = plan.join('\n');
    });

    clearBtn.addEventListener('click', ()=>{
      document.getElementById('goal').value='';
      document.getElementById('length').selectedIndex=0;
      Array.from(document.getElementById('instruments').options).forEach(o=>o.selected=false);
      document.getElementById('intensity').selectedIndex=0;
      result.textContent = 'Use the controls above and click "Build plan" to create your session summary.';
    });

    copyBtn.addEventListener('click', async ()=>{
      try{
        await navigator.clipboard.writeText(result.textContent);
        copyBtn.textContent = 'Copied';
        setTimeout(()=>copyBtn.textContent='Copy summary',1600);
      }catch(e){
        alert('Copy failed — select and copy manually.');
      }
    });
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--muted:#9db0b0;--accent:#b8e6d8}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg);color:#eaf6f1}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid rgba(255,255,255,0.03)}
    .logo{width:44px;height:44px;background:linear-gradient(135deg,var(--accent),#7fb6ff);border-radius:10px;display:grid;place-items:center}
    nav a{color:var(--muted);margin:0 8px;text-decoration:none}
    main{max-width:980px;margin:28px auto;padding:16px}
    h1{margin:0 0 6px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px}
    details{background:rgba(255,255,255,0.02);padding:12px;border-radius:8px;margin-bottom:10px}
    summary{font-weight:600;cursor:pointer}
    .muted{color:var(--muted);font-size:13px}
    .mini-cta{display:inline-block;padding:8px 10px;border-radius:8px;background:var(--accent);color:#042;text-decoration:none;font-weight:600}

    /* seat selector + packing list */
    .seat-map{display:grid;grid-template-columns:repeat(6,34px);gap:8px;justify-content:start;padding:12px;background:rgba(255,255,255,0.02);border-radius:8px}
    .seat{width:34px;height:34px;border-radius:6px;background:rgba(255,255,255,0.03);display:grid;place-items:center;color:var(--muted);cursor:pointer}
    .seat.selected{background:linear-gradient(180deg,var(--accent),#6fbfb0);color:#042}
    .seat.taken{opacity:0.25;cursor:not-allowed}
    .packing{margin-top:12px}
    .pack-item{display:flex;align-items:center;gap:8px;margin:8px 0}
    input[type=checkbox]{width:16px;height:16px}
    .export{background:#132024;color:#bff0e3;padding:8px;border-radius:8px;border:0;cursor:pointer}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Offerings</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">About</a>
      <a href="faq.html">Help</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <h1>Frequently Asked</h1>
    <p class="muted">Answers to common questions and a small interactive packing helper so you don’t forget essentials on the day.</p>

    <div class="grid">
      <div>
        <details open>
          <summary>What should I bring?</summary>
          <div class="muted" style="margin-top:8px">We provide mats and bolsters on request, but many people bring their own mat, blanket, eye cover and a bottle of water. Use the packing helper on the right to create a checklist.</div>
        </details>

        <details>
          <summary>Is sound safe for everyone?</summary>
          <div class="muted" style="margin-top:8px">Most people find sessions calming. Please do not attend if you have a current ear infection, recent head trauma, or severe uncontrolled epilepsy without clinician clearance. If you are pregnant, consult your healthcare provider. If you have concerns, contact us at {{EMAIL}} or call {{PHONE}}.</div>
        </details>

        <details>
          <summary>Arrival & late policy</summary>
          <div class="muted" style="margin-top:8px">Arrive 10–15 minutes early for check-in. Late entry is limited to preserve the experience for others; in some cases you may be asked to wait for the next opening.</div>
        </details>

        <details>
          <summary>Payment & cancellation</summary>
          <div class="muted" style="margin-top:8px">Payments are taken at booking. To cancel or reschedule, please notify us at least 24 hours in advance to receive a credit. For VIP Day and private bookings, different terms apply; see our Invest page for details.</div>
        </details>

        <details>
          <summary>Do you accept group or corporate bookings?</summary>
          <div class="muted" style="margin-top:8px">Yes — we offer tailored private immersions and workshops. Reach out via the contact form or email {{EMAIL}} for a consult.</div>
        </details>
      </div>

      <aside class="panel">
        <h3>Seat & packing helper</h3>
        <div style="font-size:13px;color:var(--muted);margin-bottom:8px">Choose imaginary seats to estimate space and generate a customized 'what to bring' list.</div>

        <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
          <label for="eventSelect">Upcoming</label>
          <select id="eventSelect" style="flex:1;padding:8px;border-radius:8px;background:transparent;color:inherit;border:1px solid rgba(255,255,255,0.03)">
            <option data-taken="3">Mon 6:30pm — Focused Drift</option>
            <option data-taken="1">Thu 7:30pm — Deep Pause</option>
            <option data-taken="5">Sat 10:00am — Weekend Reset</option>
          </select>
        </div>

        <div class="seat-map" id="seatMap" aria-hidden="false"></div>
        <div style="margin-top:10px;color:var(--muted);font-size:13px">Selected seats: <span id="count">0</span></div>

        <div class="packing">
          <h4 style="margin:8px 0 6px">Suggested packing</h4>
          <div class="pack-item"><input type="checkbox" id="mat" checked><label for="mat" class="muted">Personal mat</label></div>
          <div class="pack-item"><input type="checkbox" id="blanket" checked><label for="blanket" class="muted">Blanket</label></div>
          <div class="pack-item"><input type="checkbox" id="eye" checked><label for="eye" class="muted">Eye cover</label></div>
          <div class="pack-item"><input type="checkbox" id="water" checked><label for="water" class="muted">Water bottle</label></div>
          <div class="pack-item"><input type="checkbox" id="socks"><label for="socks" class="muted">Thick socks</label></div>

          <div style="display:flex;gap:8px;margin-top:10px">
            <button class="export" id="generateList">Generate list</button>
            <button class="export" id="copyList">Copy</button>
          </div>

          <div id="listOut" style="margin-top:12px;color:var(--muted);font-size:14px;white-space:pre-wrap"></div>
        </div>
      </aside>
    </div>

    <section style="margin-top:20px" class="panel">
      <h3>Still curious?</h3>
      <p class="muted">If your question isn't listed, send it over at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>. For immediate booking, click the Reserve link in the header.</p>
      <div style="margin-top:12px"><a class="mini-cta" href="{{PRIMARY_CTA_URL}}">Reserve your mat</a></div>
    </section>

  </main>

  <script>
    // Seat map generator
    const seatMap = document.getElementById('seatMap');
    const countEl = document.getElementById('count');
    const eventSelect = document.getElementById('eventSelect');

    function renderSeats(){
      seatMap.innerHTML = '';
      const taken = parseInt(eventSelect.selectedOptions[0].dataset.taken||0,10);
      const total = 18;
      for(let i=1;i<=total;i++){
        const div = document.createElement('div');
        div.className = 'seat';
        div.textContent = i;
        if(i<=taken){ div.classList.add('taken'); div.textContent='×'; }
        div.addEventListener('click', ()=>{
          if(div.classList.contains('taken')) return;
          div.classList.toggle('selected');
          updateCount();
        });
        seatMap.appendChild(div);
      }
      updateCount();
    }

    function updateCount(){
      const c = seatMap.querySelectorAll('.seat.selected').length;
      countEl.textContent = c;
    }

    eventSelect.addEventListener('change', renderSeats);
    renderSeats();

    // Packing list
    const generateBtn = document.getElementById('generateList');
    const copyBtn = document.getElementById('copyList');
    const listOut = document.getElementById('listOut');

    function makeList(){
      const items = [];
      if(document.getElementById('mat').checked) items.push('Mat');
      if(document.getElementById('blanket').checked) items.push('Blanket');
      if(document.getElementById('eye').checked) items.push('Eye cover');
      if(document.getElementById('water').checked) items.push('Water bottle');
      if(document.getElementById('socks').checked) items.push('Warm socks');

      const seats = document.querySelectorAll('.seat.selected').length;
      const header = 'Packing list for '+seats+' attendee'+(seats!==1?'s':'' )+':' ;
      return header+'\n- '+(items.length?items.join('\n- '):'No items selected');
    }

    generateBtn.addEventListener('click', ()=>{
      listOut.textContent = makeList();
    });

    copyBtn.addEventListener('click', async ()=>{
      try{
        await navigator.clipboard.writeText(listOut.textContent||makeList());
        copyBtn.textContent='Copied';
        setTimeout(()=>copyBtn.textContent='Copy',1200);
      }catch(e){alert('Unable to copy.');}
    });
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--card:#081218;--accent:#9be3cf;--muted:#9fb6b0}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#041015,#071018);color:#eafaf5}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 22px;border-bottom:1px solid rgba(255,255,255,0.03)}
    .logo{width:46px;height:46px;background:linear-gradient(135deg,var(--accent),#6fb7ff);border-radius:10px;display:grid;place-items:center}
    nav a{color:var(--muted);margin:0 8px;text-decoration:none}
    main{max-width:1100px;margin:26px auto;padding:18px}
    h1{margin:0 0 8px}
    .layout{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:12px}
    .event{display:flex;justify-content:space-between;align-items:center;padding:12px;border-radius:8px;background:rgba(255,255,255,0.01);margin-bottom:10px}
    .pill{background:rgba(255,255,255,0.03);padding:6px 8px;border-radius:8px;font-size:13px}
    .seat-grid{display:grid;grid-template-columns:repeat(6,40px);gap:8px;margin-top:12px}
    .seat{width:40px;height:40px;border-radius:8px;background:rgba(255,255,255,0.02);display:grid;place-items:center;cursor:pointer;color:var(--muted)}
    .seat.selected{background:linear-gradient(180deg,var(--accent),#7be0c8);color:#042}
    .seat.taken{opacity:0.3;cursor:not-allowed}
    .summary{white-space:pre-wrap;background:rgba(255,255,255,0.01);padding:12px;border-radius:8px;margin-top:12px;color:var(--muted)}
    .btn{background:var(--accent);color:#042;padding:10px 12px;border-radius:8px;border:0;cursor:pointer}
    .small{font-size:13px;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Offerings</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">About</a>
      <a href="faq.html">Help</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <h1>Reserve a seat</h1>
    <p class="small">Choose an event and simulate seating. This booking tool is local and illustrative; final reservations are processed after you submit.</p>

    <div class="layout">
      <div>
        <div class="card">
          <h3 style="margin:0 0 10px">Upcoming collections</h3>

          <div class="event">
            <div>
              <div style="font-weight:700">Wed 6:30pm — Focus Session</div>
              <div class="small">A concise 40-minute session for steady grounding</div>
            </div>
            <div style="text-align:right">
