          <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
            <label for="selectEvent" class="small">Choose event</label>
            <select id="selectEvent" style="flex:1;padding:8px;border-radius:8px;background:transparent;color:inherit;border:1px solid rgba(255,255,255,0.03)">
              <option value="wed" data-price="35" data-seats="12">Wed 6:30pm — Focus Session</option>
              <option value="fri" data-price="65" data-seats="18">Fri 7:30pm — Deep Drift</option>
              <option value="sun" data-price="28" data-seats="10">Sun 10:00am — Gentle Reset</option>
            </select>
