  <script>
    const seatGrid = document.getElementById('seatGrid');
    const selectEvent = document.getElementById('selectEvent');
    const selCount = document.getElementById('selCount');
    const summary = document.getElementById('summary');
    const reserveBtn = document.getElementById('reserve');
    const clearBtn = document.getElementById('clear');

    function renderGrid(){
      seatGrid.innerHTML='';
      const seats = parseInt(selectEvent.selectedOptions[0].dataset.seats,10)||12;
      // simulate some taken seats randomly but deterministic by seed of option value
      const val = selectEvent.value;
      const takenIndices = {wed:[2,5],fri:[1,4,7],sun:[3]};
      for(let i=1;i<=18;i++){
        const d = document.createElement('div');
        d.className='seat';
        d.textContent=i;
        if(i>seats){ d.style.opacity='0.12'; d.style.cursor='not-allowed'; }
        if(takenIndices[val] && takenIndices[val].includes(i)){
          d.classList.add('taken'); d.textContent='×';
        }
        d.addEventListener('click', ()=>{
          if(d.classList.contains('taken')||i>seats) return;
          d.classList.toggle('selected');
          updateState();
        });
        seatGrid.appendChild(d);
      }
      updateState();
    }

    function updateState(){
      const sel = seatGrid.querySelectorAll('.seat.selected');
      selCount.textContent=sel.length;
      if(sel.length===0){ summary.textContent='No seats selected.'; return; }
      const names = Array.from(sel).map(s=>s.textContent);
      const price = parseInt(selectEvent.selectedOptions[0].dataset.price,10)||0;
      summary.textContent = 'Event: '+selectEvent.selectedOptions[0].text+'\nSeats: '+names.join(', ')+'\nTotal: $'+(names.length*price);
    }

    selectEvent.addEventListener('change', renderGrid);
    clearBtn.addEventListener('click', ()=>{
      seatGrid.querySelectorAll('.seat.selected').forEach(s=>s.classList.remove('selected'));
      updateState();
    });

    reserveBtn.addEventListener('click', ()=>{
      const sel = seatGrid.querySelectorAll('.seat.selected');
      if(sel.length===0){ alert('Select at least one seat to reserve.'); return; }
      alert('Reserved '+sel.length+' seat(s) locally. Proceed to checkout to complete booking.');
    });

    // packing list
    const makePack = document.getElementById('makePack');
    const copyPack = document.getElementById('copyPack');
    const packOut = document.getElementById('packOut');

    function compilePack(){
      const items=[];
      if(document.getElementById('cbMat').checked) items.push('Personal mat');
      if(document.getElementById('cbBlanket').checked) items.push('Blanket');
      if(document.getElementById('cbEyes').checked) items.push('Eye cover');
      if(document.getElementById('cbWater').checked) items.push('Water bottle');
      const s = seatGrid.querySelectorAll('.seat.selected').length;
      let header = 'Packing list for '+(s||1)+' attendee'+(s===1?'':'s')+':';
      return header+'\n- '+(items.length?items.join('\n- '):'No items selected');
    }

    makePack.addEventListener('click', ()=>{ packOut.textContent = compilePack(); });
    copyPack.addEventListener('click', async ()=>{
      try{ await navigator.clipboard.writeText(packOut.textContent||compilePack()); copyPack.textContent='Copied'; setTimeout(()=>copyPack.textContent='Copy',1000); }catch(e){alert('Copy unavailable');}
    });

    // send email (fake)
    document.getElementById('emailIt').addEventListener('click', ()=>{
      const text = summary.textContent==='No seats selected.'? 'No selection.' : summary.textContent;
      alert('Pretend sending an email to '+ '{{EMAIL}}' +" with:\n"+text);
    });

    document.getElementById('confirm').addEventListener('click', ()=>{
      if(summary.textContent==='No seats selected.'){ alert('Select seats before confirming.'); return; }
      alert('Booking confirmed locally. We will email a confirmation to you.');
    });

    // initial
    renderGrid();
  </script>
</body>
</html>"} 
